const m = $json;
const n = (v) => Number(v ?? 0);
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const eur = (v) => n(v).toLocaleString('de-DE', { minimumFractionDigits: 2 }) + ' EUR';

const red = n(m.errors_24h) > 0 || n(m.leads_stuck) > 0;
const amber = !red && (n(m.review_oldest_days) > 2 || n(m.review_pending) > 10);
const light = red ? '🔴' : amber ? '🟡' : '🟢';
const docs = m.documents ?? {};
const row = (k, v) => '<tr><td>' + k + '</td><td align="right"><b>' + v + '</b></td></tr>';

const html = [
  '<h3>' + light + ' Tagesbericht / Daily health report – ' + $now.setZone('Europe/Berlin').toFormat('dd.MM.yyyy') + '</h3>',
  '<p>Last 24 hours, Muster GmbH order-to-cash automation.</p>',
  '<table cellpadding="4">',
  '<tr><td colspan="2"><b>Leads</b></td></tr>',
  row('New leads / Neue Leads', n(m.leads_new)),
  row('Repeat submissions', n(m.leads_repeat)),
  row('Hot leads (AI score ≥ ' + ($env.HOT_LEAD_THRESHOLD || 70) + ')', n(m.leads_hot)),
  row('Average AI score', m.leads_avg_score ?? '-'),
  row('Scored by fallback (AI unavailable)', n(m.leads_fallback)),
  row('Stuck before CRM sync', n(m.leads_stuck)),
  '<tr><td colspan="2"><b>Orders & invoices</b></td></tr>',
  row('Sales orders created in Odoo', n(m.orders_created) + ' (' + eur(m.orders_value) + ' gross)'),
  row('Invoices booked automatically', n(docs.booked)),
  row('Invoices sent to review', n(docs.needs_review)),
  row('Invoices approved by a person', n(docs.approved)),
  row('Documents rejected (not an invoice)', n(docs.rejected)),
  '<tr><td colspan="2"><b>Review queue & support</b></td></tr>',
  row('Pending review items', n(m.review_pending) + ' ' + esc(JSON.stringify(m.review_by_type ?? {}))),
  row('Oldest pending (days)', m.review_oldest_days ?? '-'),
  row('Chat order lookups / escalations', n(m.chat_lookups) + ' / ' + n(m.chat_escalations)),
  '<tr><td colspan="2"><b>Operations</b></td></tr>',
  row('Workflow errors', n(m.errors_24h)),
  '</table>',
  (m.top_errors ?? []).length
    ? '<h4>Top errors</h4><ul>' + m.top_errors.map((e) => '<li>' + esc(e.workflow_name) + ' › ' + esc(e.node_name) + ': ' + e.n + '× – ' + esc(String(e.example).slice(0, 140)) + '</li>').join('') + '</ul>'
    : '',
  '<p>Last reconciliation: ' + esc(m.last_reconciliation ?? 'none yet') + '</p>',
].join('\n');

return [{ json: {
  subject: light + ' Tagesbericht / Daily report: ' + n(m.leads_new) + ' leads, ' + n(m.orders_created) + ' orders, ' +
    n(m.errors_24h) + ' errors, ' + n(m.review_pending) + ' to review',
  html,
  status: red ? 'red' : amber ? 'amber' : 'green',
} }];

